/**
 * Dataset Perumahan Kelurahan Dangerakko — 405 rumah.
 * Sumber: DANGERAKKO_Data_Survei_Bersih.xlsx
 * Diproses dari data survei yang diunggah.
 *
 * Catatan:
 * - Struktur data mengikuti House yang digunakan pada dataset Lagaligo.
 * - Status perubahan dihitung dari 4 indikator perubahan yang tersedia:
 *   bangunan, lahan, jumlah lantai, dan pagar.
 * - K1 = 0 perubahan, K2 = 1–2 perubahan, K3 = 3+ perubahan.
 * - Workbook tidak menyediakan variabel kondisi bangunan; untuk kompatibilitas
 *   dengan UI Tapo, kondisiBangunan diisi "Baik".
 * - Workbook tidak menyediakan indikator perubahan jenis lantai/dinding/atap,
 *   sehingga ketiga flag tersebut bernilai false.
 */
export interface House {
  id: string;
  nomorUrut: number;
  namaKepalaKeluarga: string;
  alamat: string;
  rt: string;
  rw: string;
  lat: number;
  lng: number;
  statusPerubahan: 'berubah' | 'tidak_berubah';
  kondisiBangunan: string;
  klaster: 'K1' | 'K2' | 'K3';
  jumlahJenisPerubahan: number;
  luasBangunan: number | null;
  luasLahan: number | null;
  jeniLantai: string | null;
  jenisDinding: string | null;
  jumlahLantai: number | null;
  jenisAtap: string | null;
  jenisPlafon: string | null;
  pagar: string | null;
  tahunDatang: number | null;
  keterangan: string | null;
  perubahanPagar: boolean;
  perubahanLuasBangunan: boolean;
  perubahanJumlahLantai: boolean;
  perubahanJenisLantai: boolean;
  perubahanJenisDinding: boolean;
  perubahanLuasLahan: boolean;
  perubahanJenisAtap: boolean;
}

